"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/registry/default/lib/utils";

export type ChatBubbleProps = useRender.ComponentProps<"div"> & {
  align?: "start" | "end";
  variant?: "default" | "muted";
  grouped?: boolean;
};

export function ChatBubble({
  align = "start",
  variant = "default",
  grouped = false,
  className,
  render,
  ...props
}: ChatBubbleProps): ReactElement {
  const defaultProps = {
    "data-slot": "chat-bubble",
    "data-align": align,
    "data-variant": variant,
    "data-grouped": grouped || undefined,
    className: cn(
      "relative flex min-w-0 flex-col gap-2 rounded-2xl px-3.5 py-2.5 text-foreground",
      variant === "default" ? "bg-foreground/12" : "bg-foreground/4",
      !grouped && (align === "end" ? "rounded-se-md" : "rounded-ss-md"),
      className,
    ),
  };

  return useRender({
    defaultTagName: "div",
    render,
    props: mergeProps<"div">(defaultProps, props),
  });
}

export function ChatBubbleReactions({
  className,
  ...props
}: ComponentProps<"div">): ReactElement {
  return (
    <div
      data-slot="chat-bubble-reactions"
      className={cn("flex flex-wrap gap-1 px-0.5", className)}
      {...props}
    />
  );
}

"use client";

import { ChevronDownIcon, ChevronUpIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { useState } from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  Collapsible,
  CollapsiblePanel,
  CollapsibleTrigger,
} from "@/registry/default/ui/collapsible";
import { splitChatMessagePreview } from "./lib/split-chat-message-preview";

export type ChatCollapsibleMessageProps = {
  text: string;
  showMoreLabel: string;
  showLessLabel: string;
  side: "incoming" | "outgoing";
  maxPreviewLength?: number;
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  renderText?: (text: string) => ReactNode;
  className?: string;
};

function renderPlainText(text: string): ReactElement {
  return (
    <p className="m-0 whitespace-pre-wrap break-words text-sm leading-[1.55]">
      {text}
    </p>
  );
}

function ChatCollapsibleMessage({
  text,
  showMoreLabel,
  showLessLabel,
  side,
  maxPreviewLength,
  defaultOpen = false,
  open,
  onOpenChange,
  renderText = renderPlainText,
  className,
}: ChatCollapsibleMessageProps): ReactElement {
  const { preview, remainder } = splitChatMessagePreview(
    text,
    maxPreviewLength,
  );
  if (!remainder) {
    return <div className={cn("min-w-0", className)}>{renderText(text)}</div>;
  }

  return (
    <ExpandableChatMessage
      text={text}
      preview={preview}
      renderText={renderText}
      showMoreLabel={showMoreLabel}
      showLessLabel={showLessLabel}
      side={side}
      className={className}
      defaultOpen={defaultOpen}
      open={open}
      onOpenChange={onOpenChange}
    />
  );
}

function ExpandableChatMessage({
  text,
  preview,
  renderText,
  showMoreLabel,
  showLessLabel,
  side,
  className,
  defaultOpen,
  open: controlledOpen,
  onOpenChange,
}: {
  text: string;
  preview: string;
  renderText: (text: string) => ReactNode;
  showMoreLabel: string;
  showLessLabel: string;
  side: "incoming" | "outgoing";
  className?: string;
  defaultOpen: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}): ReactElement {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const open = controlledOpen ?? internalOpen;
  const setOpen = (nextOpen: boolean): void => {
    if (controlledOpen === undefined) setInternalOpen(nextOpen);
    onOpenChange?.(nextOpen);
  };
  const Icon = open ? ChevronUpIcon : ChevronDownIcon;

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className={cn("flex min-w-0 flex-col", className)}
    >
      <div className="grid">
        <div
          data-slot="chat-collapsible-preview"
          aria-hidden={open || undefined}
          className={cn(
            "mask-[linear-gradient(to_bottom,black_calc(100%-3rem),transparent)] col-start-1 row-start-1 self-start",
            open && "invisible",
          )}
        >
          {renderText(preview)}
        </div>
        <CollapsiblePanel className="col-start-1 row-start-1 min-w-0 motion-reduce:transition-none">
          <div
            aria-hidden={!open || undefined}
            className={open ? undefined : "invisible"}
          >
            {renderText(text)}
          </div>
        </CollapsiblePanel>
      </div>
      <CollapsibleTrigger
        type="button"
        className={cn(
          "mt-2 flex w-fit items-center gap-1 text-start text-xs outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring",
          side === "outgoing"
            ? "text-foreground/80 hover:text-foreground"
            : "text-muted-foreground hover:text-foreground",
        )}
      >
        {open ? showLessLabel : showMoreLabel}
        <Icon aria-hidden="true" className="size-3.5 shrink-0" />
      </CollapsibleTrigger>
    </Collapsible>
  );
}

export { ChatCollapsibleMessage, splitChatMessagePreview };

"use client";

import { ArrowUpIcon } from "lucide-react";
import type { ReactElement, RefObject } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupTextarea,
} from "@/registry/default/ui/input-group";
import { ScrollArea } from "@/registry/default/ui/scroll-area";
import type { TextareaProps } from "@/registry/default/ui/textarea";
import {
  Tooltip,
  TooltipPopup,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";

export type ChatComposerFieldProps = {
  textareaProps: Omit<TextareaProps, "unstyled" | "aria-label">;
  textareaLabel: string;
  sendLabel: string;
  sendDisabled: boolean;
  sendPlacement?: "block-end" | "inline-end";
  scrollAreaRef?: RefObject<HTMLDivElement | null>;
};

export function ChatComposerField({
  textareaProps,
  textareaLabel,
  sendLabel,
  sendDisabled,
  sendPlacement = "block-end",
  scrollAreaRef,
}: ChatComposerFieldProps): ReactElement {
  const inlineSend = sendPlacement === "inline-end";
  const input = (
    <InputGroupTextarea
      {...textareaProps}
      aria-label={textareaLabel}
      className={cn(
        "flex-1 *:block *:overflow-hidden",
        inlineSend && "*:min-h-0! *:min-w-0 *:py-1.25!",
        textareaProps.className,
      )}
    />
  );

  return (
    <InputGroup
      className={cn(
        inlineSend &&
          "items-end rounded-[1.125rem] leading-6 before:rounded-[calc(1.125rem-1px)] sm:text-base",
      )}
    >
      <ScrollArea
        ref={scrollAreaRef}
        scrollFade
        className={cn(
          "h-auto min-w-0 overflow-hidden pointer-coarse:[&>[data-slot=scroll-area-scrollbar]]:hidden",
          inlineSend
            ? "max-h-24 *:data-[slot=scroll-area-viewport]:max-h-24"
            : "max-h-36 *:data-[slot=scroll-area-viewport]:max-h-36",
        )}
        data-slot="chat-composer-scroll-area"
      >
        {input}
      </ScrollArea>
      <InputGroupAddon
        align={sendPlacement}
        className={cn(
          "justify-end",
          inlineSend && "self-end py-0.75 pe-0.75 has-[>button]:me-0",
        )}
      >
        <Tooltip>
          <TooltipTrigger
            render={
              <Button
                type="submit"
                size={inlineSend ? "icon-xs" : "icon"}
                disabled={sendDisabled}
                aria-label={sendLabel}
                className={cn(
                  "rounded-full transition-transform before:rounded-full active:scale-95 disabled:border-transparent disabled:bg-muted disabled:text-muted-foreground disabled:opacity-100 motion-reduce:transform-none",
                  inlineSend && "sm:size-7",
                )}
              />
            }
          >
            <ArrowUpIcon
              className={inlineSend ? "size-4" : "size-4.5"}
              aria-hidden="true"
            />
          </TooltipTrigger>
          <TooltipPopup side="bottom">{sendLabel}</TooltipPopup>
        </Tooltip>
      </InputGroupAddon>
    </InputGroup>
  );
}

"use client";

import type { KeyboardEvent, ReactElement, ReactNode, RefObject } from "react";
import { useId, useRef, useState } from "react";
import { useMediaQuery } from "@/registry/default/hooks/use-media-query";
import { cn } from "@/registry/default/lib/utils";
import { ChatComposerField } from "./chat-composer-field";
import { ChatMentionSuggestions } from "./chat-mentions";
import {
  deleteMentionBackward,
  getMentionQuery,
  insertMention,
} from "./lib/chat-mention-text";

export type ChatMentionOption = {
  id: string;
  name: string;
  insertText: string;
  avatar?: ReactNode;
};
export type ChatComposerProps = {
  draft: string;
  onDraftChange: (value: string) => void;
  onSend: (value: string) => void;
  textareaRef?: RefObject<HTMLTextAreaElement | null>;
  mentions?: { options: readonly ChatMentionOption[]; label: string };
  textareaLabel: string;
  sendLabel: string;
  placeholder?: string;
  notice?: ReactNode;
  hint?: ReactNode;
  disabled?: boolean;
  compact?: boolean;
  className?: string;
};

export function ChatComposer({
  draft,
  onDraftChange,
  onSend,
  textareaRef: suppliedTextareaRef,
  mentions,
  textareaLabel,
  sendLabel,
  placeholder,
  notice,
  hint,
  disabled = false,
  compact: compactProp,
  className,
}: ChatComposerProps): ReactElement {
  const suggestionId = useId();
  const hintId = useId();
  const ownTextareaRef = useRef<HTMLTextAreaElement>(null);
  const textareaRef = suppliedTextareaRef ?? ownTextareaRef;
  const scrollAreaRef = useRef<HTMLDivElement>(null);
  const fieldRef = useRef<HTMLDivElement>(null);
  const [caret, setCaret] = useState(0);
  const [activeSuggestion, setActiveSuggestion] = useState(0);
  const [dismissed, setDismissed] = useState(false);
  const touchInput = useMediaQuery({ pointer: "coarse" });
  const wideViewport = useMediaQuery("md");
  const compact = compactProp ?? !wideViewport;
  const mention = !mentions || dismissed ? null : getMentionQuery(draft, caret);
  const suggestions = (mentions?.options ?? []).filter((option) =>
    option.insertText
      .toLowerCase()
      .startsWith(mention?.query.toLowerCase() ?? ""),
  );
  const showSuggestions = Boolean(mention && suggestions.length);

  const focusAt = (position: number): void => {
    window.requestAnimationFrame(() => {
      textareaRef.current?.focus();
      textareaRef.current?.setSelectionRange(position, position);
    });
  };

  const selectMention = (id: string): void => {
    const option = mentions?.options.find((item) => item.id === id);
    if (!option) return;
    if (!mention) return;
    const result = insertMention(draft, mention, option.insertText);
    onDraftChange(result.text);
    setCaret(result.caret);
    setDismissed(true);
    focusAt(result.caret);
  };

  const send = (): void => {
    if (disabled || !draft.trim()) return;
    onSend(draft.trim());
    setCaret(0);
    setDismissed(false);
    focusAt(0);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>): void => {
    if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229)
      return;
    if (touchInput && event.key === "Enter") return;
    if (
      mentions &&
      event.key === "Backspace" &&
      (event.altKey || event.ctrlKey)
    ) {
      const textarea = event.currentTarget;
      if (textarea.selectionStart === textarea.selectionEnd) {
        const result = deleteMentionBackward(draft, textarea.selectionStart);
        if (result) {
          event.preventDefault();
          onDraftChange(result.text);
          setCaret(result.caret);
          setDismissed(true);
          focusAt(result.caret);
          return;
        }
      }
    }
    if (mention) {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        setDismissed(true);
        return;
      }
      if (
        suggestions.length &&
        (event.key === "ArrowDown" || event.key === "ArrowUp")
      ) {
        event.preventDefault();
        setActiveSuggestion(
          (current) =>
            (current +
              (event.key === "ArrowDown" ? 1 : -1) +
              suggestions.length) %
            suggestions.length,
        );
        return;
      }
      if (suggestions.length && event.key === "Enter" && !event.shiftKey) {
        event.preventDefault();
        const suggestion = suggestions[activeSuggestion] ?? suggestions[0];
        if (suggestion) selectMention(suggestion.id);
        return;
      }
    }
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      send();
    }
  };

  return (
    <form
      className={cn("relative z-20 flex shrink-0 flex-col gap-2.5", className)}
      onSubmit={(event) => {
        event.preventDefault();
        send();
      }}
    >
      <fieldset
        disabled={disabled}
        className="m-0 min-w-0 border-0 p-0 disabled:opacity-50"
      >
        <div ref={fieldRef} className="relative">
          {mentions && (
            <ChatMentionSuggestions
              id={suggestionId}
              open={showSuggestions}
              label={mentions.label}
              options={suggestions}
              activeId={(suggestions[activeSuggestion] ?? suggestions[0])?.id}
              onActiveIdChange={(id) =>
                setActiveSuggestion(
                  suggestions.findIndex((option) => option.id === id),
                )
              }
              anchor={fieldRef}
              onDismiss={() => setDismissed(true)}
              onSelect={selectMention}
            />
          )}
          <ChatComposerField
            textareaLabel={textareaLabel}
            scrollAreaRef={scrollAreaRef}
            sendLabel={sendLabel}
            sendDisabled={!draft.trim()}
            sendPlacement={compact ? "inline-end" : "block-end"}
            textareaProps={{
              ref: textareaRef,
              rows: 1,
              value: draft,
              enterKeyHint: touchInput ? "enter" : undefined,
              "aria-describedby": touchInput ? undefined : hintId,
              "aria-autocomplete": mentions ? "list" : undefined,
              "aria-expanded": mentions ? showSuggestions : undefined,
              "aria-controls": showSuggestions ? suggestionId : undefined,
              "aria-activedescendant": showSuggestions
                ? `${suggestionId}-${(suggestions[activeSuggestion] ?? suggestions[0])?.id}`
                : undefined,
              placeholder,
              onKeyDown,
              onSelect: (event) => setCaret(event.currentTarget.selectionStart),
              onChange: (event) => {
                const textarea = event.currentTarget;
                const caretAtEnd =
                  textarea.selectionEnd === textarea.value.length;
                onDraftChange(event.target.value);
                setCaret(event.target.selectionStart);
                setActiveSuggestion(0);
                setDismissed(false);
                if (caretAtEnd) {
                  window.requestAnimationFrame(() => {
                    const viewport =
                      scrollAreaRef.current?.querySelector<HTMLDivElement>(
                        ':scope > [data-slot="scroll-area-viewport"]',
                      );
                    if (viewport) viewport.scrollTop = viewport.scrollHeight;
                  });
                }
              },
            }}
          />
        </div>
      </fieldset>
      <div
        className={cn(
          touchInput && !notice
            ? "sr-only"
            : "flex min-h-4 items-center justify-between px-1 text-muted-foreground text-xs",
          disabled && "opacity-50",
        )}
      >
        <span role="status" aria-live="polite">
          {notice}
        </span>
        {!touchInput && (
          <span
            id={hintId}
            className={notice ? "sr-only" : "ms-auto pointer-coarse:hidden"}
          >
            {hint}
          </span>
        )}
      </div>
    </form>
  );
}

"use client";

import type { ComponentProps, ReactElement, ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  ScrollAreaPrimitive,
  ScrollBar,
} from "@/registry/default/ui/scroll-area";
import { ChatJumpToLatestButton } from "./chat-jump-to-latest-button";
import type { ChatScrollController } from "./hooks/use-chat-scroll";

export type ChatConversationProps = ComponentProps<"div"> & {
  scroll: ChatScrollController;
  label: string;
  jumpLabel: ReactNode;
  contentClassName?: string;
  overlay?: ReactNode;
  inactive?: boolean;
};

export function ChatConversation({
  scroll,
  label,
  jumpLabel,
  contentClassName,
  children,
  overlay,
  inactive = false,
  className,
  ...props
}: ChatConversationProps): ReactElement {
  return (
    <div
      data-slot="chat-conversation"
      className={cn("relative flex min-h-0 flex-1 flex-col", className)}
      {...props}
    >
      <ScrollAreaPrimitive.Root
        inert={inactive}
        className="size-full min-h-0 touch-auto before:pointer-events-none before:absolute before:inset-x-0 before:top-0 before:z-10 before:h-6 before:bg-linear-to-b before:from-popover before:to-transparent before:opacity-0 before:content-[''] after:pointer-events-none after:absolute after:inset-x-0 after:bottom-0 after:z-10 after:h-6 after:bg-linear-to-t after:from-popover after:to-transparent after:opacity-0 after:content-[''] data-overflow-y-end:after:opacity-100 data-overflow-y-start:before:opacity-100"
      >
        <ScrollAreaPrimitive.Viewport
          ref={scroll.viewportRef}
          role="log"
          aria-label={label}
          aria-relevant="additions text"
          data-slot="scroll-area-viewport"
          className="h-full rounded-[inherit] outline-none transition-shadow focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset data-has-overflow-y:overscroll-y-contain data-has-overflow-x:overscroll-x-contain"
          onScroll={scroll.onScroll}
        >
          <ScrollAreaPrimitive.Content
            data-slot="scroll-area-content"
            className={cn("px-4 pb-4", contentClassName)}
            style={{ minWidth: 0 }}
          >
            {children}
          </ScrollAreaPrimitive.Content>
        </ScrollAreaPrimitive.Viewport>
        <ScrollBar orientation="vertical" />
        <ScrollBar orientation="horizontal" />
        <ScrollAreaPrimitive.Corner data-slot="scroll-area-corner" />
      </ScrollAreaPrimitive.Root>
      {scroll.showJump && !inactive && (
        <div className="pointer-events-none absolute inset-x-0 bottom-3 z-30 flex justify-center">
          <ChatJumpToLatestButton onClick={scroll.scrollToLatest}>
            {jumpLabel}
          </ChatJumpToLatestButton>
        </div>
      )}
      {overlay}
    </div>
  );
}

"use client";

import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/registry/default/lib/utils";

export function ChatDatePill({
  className,
  ...props
}: ComponentProps<"div">): ReactElement {
  return (
    <div
      data-slot="chat-date-pill"
      className={cn(
        "pointer-events-none sticky top-4 z-20 mx-auto flex h-6 w-fit items-center justify-center rounded-full border bg-popover/90 px-2 font-medium text-foreground text-xs backdrop-blur-xs",
        className,
      )}
      {...props}
    />
  );
}

"use client";

import {
  CheckCheckIcon,
  CheckIcon,
  CircleAlertIcon,
  ClockIcon,
} from "lucide-react";
import type { ReactElement } from "react";
import { cn } from "@/registry/default/lib/utils";

export type ChatDeliveryIndicatorProps = {
  status: "sending" | "sent" | "delivered" | "read" | "failed";
  label: string;
};

export function ChatDeliveryIndicator({
  status,
  label,
}: ChatDeliveryIndicatorProps): ReactElement {
  const Icon = {
    sending: ClockIcon,
    sent: CheckIcon,
    delivered: CheckCheckIcon,
    read: CheckCheckIcon,
    failed: CircleAlertIcon,
  }[status];

  return (
    <span
      role="status"
      aria-label={label}
      title={label}
      data-slot="chat-delivery-indicator"
    >
      <Icon
        aria-hidden="true"
        className={cn(
          "size-3",
          status === "read" && "text-sky-600 dark:text-sky-400",
          status === "failed" && "text-destructive",
        )}
      />
    </span>
  );
}

"use client";

import { ArrowDownIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button, type ButtonProps } from "@/registry/default/ui/button";

export type ChatJumpToLatestButtonProps = Omit<
  ButtonProps,
  "children" | "size" | "variant"
> & {
  children: ReactNode;
};

export function ChatJumpToLatestButton({
  className,
  children,
  ...props
}: ChatJumpToLatestButtonProps): ReactElement {
  return (
    <div
      data-slot="chat-jump-to-latest"
      className="rounded-full bg-popover/90 backdrop-blur-xs"
    >
      <Button
        variant="outline"
        size="xs"
        className={cn(
          "pointer-events-auto gap-2 rounded-full before:rounded-full",
          className,
        )}
        {...props}
      >
        <ArrowDownIcon aria-hidden="true" />
        {children}
      </Button>
    </div>
  );
}

"use client";

import type { ComponentProps, ReactElement, ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";

export type ChatMemberEntry = {
  id: string;
  name: ReactNode;
  avatar?: ReactNode;
  badges?: ReactNode;
  action?: ReactNode;
  dimmed?: boolean;
};

export type ChatMemberListProps = ComponentProps<"ul"> & {
  members: readonly ChatMemberEntry[];
};

export function ChatMemberList({
  members,
  className,
  ...props
}: ChatMemberListProps): ReactElement {
  return (
    <ul
      data-slot="chat-member-list"
      className={cn("m-0 flex list-none flex-col gap-2 p-0", className)}
      {...props}
    >
      {members.map((member) => (
        <li key={member.id} className="flex min-w-0 items-center gap-3">
          {member.avatar}
          <div className="flex min-w-0 flex-1 flex-wrap items-center gap-x-1.5 gap-y-1">
            <span
              className={cn(
                "truncate text-sm",
                member.dimmed ? "text-muted-foreground" : "font-medium",
              )}
            >
              {member.name}
            </span>
            {member.badges}
          </div>
          {member.action}
        </li>
      ))}
    </ul>
  );
}

export type ChatMemberSectionProps = ChatMemberListProps & {
  label: string;
  heading?: ReactNode;
};

export function ChatMemberSection({
  label,
  heading,
  members,
  ...props
}: ChatMemberSectionProps): ReactElement | null {
  if (!members.length) return null;
  return (
    <section aria-label={label} className="flex flex-col gap-4">
      {heading && (
        <h3 className="m-0 flex items-center gap-2 font-medium text-muted-foreground text-xs">
          {heading}
        </h3>
      )}
      <ChatMemberList members={members} {...props} />
    </section>
  );
}

"use client";

import type { ComponentProps, ReactElement, ReactNode } from "react";
import { useEffect, useRef } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import { Popover, PopoverPopup } from "@/registry/default/ui/popover";
import { ScrollArea } from "@/registry/default/ui/scroll-area";

export type ChatMentionSuggestionsProps<TId extends string> = {
  id: string;
  open: boolean;
  label: string;
  options: readonly { id: TId; name: string; avatar?: ReactNode }[];
  activeId?: TId;
  anchor: ComponentProps<typeof PopoverPopup>["anchor"];
  onActiveIdChange?: (id: TId) => void;
  onDismiss: () => void;
  onSelect: (id: TId) => void;
};

export function ChatMentionSuggestions<TId extends string>({
  id,
  open,
  label,
  options,
  activeId,
  anchor,
  onActiveIdChange,
  onDismiss,
  onSelect,
}: ChatMentionSuggestionsProps<TId>): ReactElement | null {
  const activeRef = useRef<HTMLButtonElement>(null);
  // biome-ignore lint/correctness/useExhaustiveDependencies: Changing the active option must scroll its updated ref into view.
  useEffect(() => {
    if (!open) return;
    const frame = requestAnimationFrame(() =>
      activeRef.current?.scrollIntoView({ block: "nearest" }),
    );
    return () => cancelAnimationFrame(frame);
  }, [activeId, open]);
  if (!options.length) return null;
  return (
    <Popover open={open} onOpenChange={(nextOpen) => !nextOpen && onDismiss()}>
      <PopoverPopup
        anchor={anchor}
        side="top"
        align="start"
        id={id}
        role="listbox"
        aria-label={label}
        initialFocus={false}
        finalFocus={false}
        data-slot="chat-mention-suggestions"
        className="h-auto! w-72 max-w-(--available-width) [&>[data-slot=popover-viewport]]:overflow-visible [&>[data-slot=popover-viewport]]:p-0 [&>[data-slot=popover-viewport]]:[--viewport-inline-padding:0px]"
      >
        <ScrollArea
          overscrollContain
          scrollbarGutter
          scrollFade
          className="max-h-[min(var(--available-height),16rem)] *:data-[slot=scroll-area-viewport]:max-h-[min(var(--available-height),16rem)]"
        >
          <div className="scroll-py-1 px-1 py-1">
            {options.map((option) => (
              <Button
                key={option.id}
                ref={option.id === activeId ? activeRef : undefined}
                id={`${id}-${option.id}`}
                role="option"
                aria-selected={option.id === activeId}
                tabIndex={-1}
                variant="ghost"
                className={cn(
                  "flex h-auto min-h-8 w-full cursor-default select-none justify-start gap-2 rounded-sm border-0 py-1 ps-2 pe-2 text-start font-normal before:rounded-sm sm:h-auto sm:min-h-7",
                  option.id === activeId && "bg-accent text-accent-foreground",
                )}
                onPointerMove={() => onActiveIdChange?.(option.id)}
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => onSelect(option.id)}
              >
                {option.avatar && (
                  <span aria-hidden="true" className="flex shrink-0">
                    {option.avatar}
                  </span>
                )}
                <span className="min-w-0 truncate">{option.name}</span>
              </Button>
            ))}
          </div>
        </ScrollArea>
      </PopoverPopup>
    </Popover>
  );
}

