import { type RefObject, useEffect } from "react";

export function useChatPopupDismissal(
  active: boolean,
  triggerRef: RefObject<HTMLElement | null>,
  onDismiss: () => void,
): void {
  useEffect(() => {
    const trigger = triggerRef.current;
    if (!active || !trigger) return;
    const onScroll = (event: Event): void => {
      if (event.target instanceof Node && event.target.contains(trigger))
        onDismiss();
    };
    document.addEventListener("scroll", onScroll, true);
    return () => document.removeEventListener("scroll", onScroll, true);
  }, [active, triggerRef, onDismiss]);
}

"use client";

import {
  type UIEvent,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

export type ChatScrollOptions = {
  active?: boolean;
  paused?: boolean;
  itemCount: number;
  layoutKey?: string | number;
  onReachEnd?: () => void;
};

export function useChatScroll({
  active = true,
  paused = false,
  itemCount,
  layoutKey,
  onReachEnd,
}: ChatScrollOptions) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const atBottomRef = useRef(true);
  const [showJump, setShowJump] = useState(false);

  // biome-ignore lint/correctness/useExhaustiveDependencies: Follow content changes before scroll events can misinterpret the new height.
  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    if (!active || paused || !viewport) return;
    // Follow before a scroll event can interpret newly added height as scrolling away.
    if (atBottomRef.current) {
      viewport.scrollTop = viewport.scrollHeight;
      setShowJump(false);
    } else {
      setShowJump(
        viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight > 64,
      );
    }
  }, [active, paused, itemCount, layoutKey]);

  useEffect(() => {
    if (!active || paused) return;
    let observer: ResizeObserver | undefined;
    const frame = requestAnimationFrame(() => {
      const viewport = viewportRef.current;
      if (!viewport) return;
      observer = new ResizeObserver(() => {
        if (atBottomRef.current) viewport.scrollTop = viewport.scrollHeight;
      });
      observer.observe(viewport);
      if (viewport.firstElementChild)
        observer.observe(viewport.firstElementChild);
    });
    return () => {
      cancelAnimationFrame(frame);
      observer?.disconnect();
    };
  }, [active, paused]);

  const updatePosition = (): void => {
    const viewport = viewportRef.current;
    atBottomRef.current = Boolean(
      viewport &&
        viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight < 64,
    );
  };

  const onScroll = (_event: UIEvent<HTMLDivElement>): void => {
    if (paused) return;
    updatePosition();
    setShowJump(!atBottomRef.current);
    if (atBottomRef.current) onReachEnd?.();
  };

  const resetScroll = (atBottom = true): void => {
    atBottomRef.current = atBottom;
    setShowJump(!atBottom);
    requestAnimationFrame(() => {
      const viewport = viewportRef.current;
      if (viewport) viewport.scrollTop = atBottom ? viewport.scrollHeight : 0;
    });
  };

  const scrollToLatest = (): void => {
    atBottomRef.current = true;
    const viewport = viewportRef.current;
    viewport?.scrollTo({
      top: viewport.scrollHeight,
      behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "auto"
        : "smooth",
    });
  };

  return {
    viewportRef,
    atBottomRef,
    showJump,
    onScroll,
    resetScroll,
    updatePosition,
    scrollToLatest,
  };
}

export type ChatScrollController = ReturnType<typeof useChatScroll>;

export function splitChatMessagePreview(
  text: string,
  maxPreviewLength = 500,
): { preview: string; remainder: string | null } {
  if (text.length <= maxPreviewLength)
    return { preview: text, remainder: null };

  const limit = Math.max(1, Math.floor(maxPreviewLength));
  const paragraphBreak = text.lastIndexOf("\n\n", limit);
  let splitAt = limit;
  if (paragraphBreak > limit / 2) {
    splitAt = paragraphBreak;
  } else {
    for (let index = limit; index > 0; index--) {
      if (/\s/u.test(text[index] ?? "")) {
        splitAt = index;
        break;
      }
    }
  }

  if (typeof Intl.Segmenter === "function") {
    const segments = new Intl.Segmenter(undefined, {
      granularity: "grapheme",
    }).segment(text);
    for (const { index, segment } of segments) {
      if (index + segment.length > splitAt) {
        splitAt = index || segment.length;
        break;
      }
    }
  } else if (/^[\uDC00-\uDFFF]$/u.test(text[splitAt] ?? "")) {
    splitAt = splitAt === 1 ? 2 : splitAt - 1;
  }

  return {
    preview: text.slice(0, splitAt).trimEnd(),
    remainder: text.slice(splitAt).trimStart() || null,
  };
}

export type MentionQuery = { start: number; end: number; query: string };

export function getMentionQuery(
  text: string,
  caret: number,
): MentionQuery | null {
  const match = text.slice(0, caret).match(/(?:^|\s)@([\p{L}\p{N}_.-]*)$/u);
  if (match?.[1] === undefined) return null;
  const suffix = text.slice(caret).match(/^[\p{L}\p{N}_.-]*/u)?.[0] ?? "";
  return {
    start: caret - match[1].length - 1,
    end: caret + suffix.length,
    query: match[1],
  };
}

export function insertMention(
  text: string,
  mention: MentionQuery,
  handle: string,
): { text: string; caret: number } {
  const remainder = text.slice(mention.end);
  const separator = /^[\n.,!?;:)]/.test(remainder) ? "" : " ";
  const prefix = `${text.slice(0, mention.start)}@${handle}${separator}`;
  const suffix = remainder.replace(/^ /, "");
  return { text: prefix + suffix, caret: prefix.length };
}

export function deleteMentionBackward(
  text: string,
  caret: number,
): { text: string; caret: number } | null {
  const match = text.slice(0, caret).match(/(?:^|\s)@([\p{L}\p{N}_.-]+)( *)$/u);
  if (match?.[1] === undefined || match[2] === undefined) return null;
  const start = caret - match[1].length - match[2].length - 1;
  return { text: text.slice(0, start) + text.slice(caret), caret: start };
}
